  "title": "Expose a process timestamp in the current-state model",
  "body": "Adds a timestamp column to the process model and documents it in the schema catalog. Retains one row per process based on the latest event."
}

create table process_events (
    event_id integer primary key,
    process_id integer not null,
    event_type text not null check (event_type in ('created', 'started', 'cleared')),
    occurred_at text not null
);

